local GardenSoilScreenMaker = {}
local PRODUCTS = {
    iron_gardensoilscreen = { name = "Železni sitana za prst", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni sitana za prst za vrtnarje." },
    bronze_gardensoilscreen = { name = "Bronast sitana za prst", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast sitana za prst za vrtnarje." },
    silver_gardensoilscreen = { name = "Srebrn sitana za prst", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn sitana za prst za vrtnarje." },
    gilded_gardensoilscreen = { name = "Pozlačen sitana za prst", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen sitana za prst za vrtnarje." },
    jewel_set_gardensoilscreen = { name = "Draguljast sitana za prst", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast sitana za prst za vrtnarje." },
    royal_sovereign_gardensoilscreen = { name = "Kraljevski suveren sitana za prst", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren sitana za prst z biseri za krono." },
}
local BUILDINGS = {
    gardensoilscreen_workshop = { name = "Gardensoilscreen delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    gardensoilscreen_house = { name = "Gardensoilscreen hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_gardensoilscreen_atelier = { name = "Mojstrski gardensoilscreen atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_gardensoilscreen_palace = { name = "Suverena gardensoilscreen palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GardenSoilScreenMaker.ironStock=12; GardenSoilScreenMaker.bronzeStock=10; GardenSoilScreenMaker.woodStock=16; GardenSoilScreenMaker.leatherStock=10; GardenSoilScreenMaker.silverStock=8; GardenSoilScreenMaker.goldStock=6; GardenSoilScreenMaker.jewelStock=4; GardenSoilScreenMaker.pearlStock=4
GardenSoilScreenMaker.productStock = {}; GardenSoilScreenMaker.buildings = {}; GardenSoilScreenMaker.maker = nil; GardenSoilScreenMaker.activeMaking = {}; GardenSoilScreenMaker.totalProducts = 0; GardenSoilScreenMaker.dayTimer = 0
function GardenSoilScreenMaker.init() GardenSoilScreenMaker.ironStock=12; GardenSoilScreenMaker.bronzeStock=10; GardenSoilScreenMaker.woodStock=16; GardenSoilScreenMaker.leatherStock=10; GardenSoilScreenMaker.silverStock=8; GardenSoilScreenMaker.goldStock=6; GardenSoilScreenMaker.jewelStock=4; GardenSoilScreenMaker.pearlStock=4; GardenSoilScreenMaker.productStock={}; GardenSoilScreenMaker.buildings={}; GardenSoilScreenMaker.maker=nil; GardenSoilScreenMaker.activeMaking={}; GardenSoilScreenMaker.totalProducts=0; GardenSoilScreenMaker.dayTimer=0; print("[GardenSoilScreenMaker] Royal Garden Soil Screen Maker System initialized (6 products, 4 buildings)") end
function GardenSoilScreenMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenSoilScreenMaker.maker={name=n or ("Sitnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sitnikar najet: %s (spretnost: %d)",GardenSoilScreenMaker.maker.name,s),"success") end; return true end
function GardenSoilScreenMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenSoilScreenMaker.build(id) local ok,e=GardenSoilScreenMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenSoilScreenMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenSoilScreenMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenSoilScreenMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenSoilScreenMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenSoilScreenMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenSoilScreenMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenSoilScreenMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenSoilScreenMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenSoilScreenMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenSoilScreenMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenSoilScreenMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenSoilScreenMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenSoilScreenMaker.buildings==0 then return false,"Potrebna sitnicna delavnica" end; if not GardenSoilScreenMaker.maker then return false,"Potreben sitnikar" end; return true end
function GardenSoilScreenMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenSoilScreenMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenSoilScreenMaker.ironStock=GardenSoilScreenMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenSoilScreenMaker.bronzeStock=GardenSoilScreenMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenSoilScreenMaker.woodStock=GardenSoilScreenMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenSoilScreenMaker.leatherStock=GardenSoilScreenMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenSoilScreenMaker.silverStock=GardenSoilScreenMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenSoilScreenMaker.goldStock=GardenSoilScreenMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenSoilScreenMaker.jewelStock=GardenSoilScreenMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenSoilScreenMaker.pearlStock=GardenSoilScreenMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenSoilScreenMaker.maker then t=math.max(1,t-math.floor(GardenSoilScreenMaker.maker.skill/13)) end; table.insert(GardenSoilScreenMaker.activeMaking,{id="gardensoilscreen_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenSoilScreenMaker.completeMaking(m) local q=1.0+(GardenSoilScreenMaker.getQualityBonus()/100); if GardenSoilScreenMaker.maker then q=q+(GardenSoilScreenMaker.maker.skill/140) end; q=math.min(2.5,q); GardenSoilScreenMaker.productStock[m.productType]=(GardenSoilScreenMaker.productStock[m.productType] or 0)+m.quantity; GardenSoilScreenMaker.totalProducts=GardenSoilScreenMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenSoilScreenMaker.maker then GardenSoilScreenMaker.maker.itemsMade=GardenSoilScreenMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenSoilScreenMaker.maker.skill=math.min(100,GardenSoilScreenMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sito izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardensoilscreen.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenSoilScreenMaker.update(dt) if not _G.state then return end; GardenSoilScreenMaker.dayTimer=GardenSoilScreenMaker.dayTimer+dt; if GardenSoilScreenMaker.dayTimer>=30 then GardenSoilScreenMaker.dayTimer=0; for i=#GardenSoilScreenMaker.activeMaking,1,-1 do local m=GardenSoilScreenMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenSoilScreenMaker.completeMaking(m); table.remove(GardenSoilScreenMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenSoilScreenMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenSoilScreenMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenSoilScreenMaker.getStats() return {ironStock=GardenSoilScreenMaker.ironStock,bronzeStock=GardenSoilScreenMaker.bronzeStock,woodStock=GardenSoilScreenMaker.woodStock,leatherStock=GardenSoilScreenMaker.leatherStock,silverStock=GardenSoilScreenMaker.silverStock,goldStock=GardenSoilScreenMaker.goldStock,jewelStock=GardenSoilScreenMaker.jewelStock,pearlStock=GardenSoilScreenMaker.pearlStock,productStock=GardenSoilScreenMaker.productStock,numBuildings=#GardenSoilScreenMaker.buildings,hasMaker=GardenSoilScreenMaker.maker~=nil,makerName=GardenSoilScreenMaker.maker and GardenSoilScreenMaker.maker.name or "—",makerSkill=GardenSoilScreenMaker.maker and GardenSoilScreenMaker.maker.skill or 0,activeMaking=#GardenSoilScreenMaker.activeMaking,totalProducts=GardenSoilScreenMaker.totalProducts} end
return GardenSoilScreenMaker
